import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong candidates based on t-statistics
    strong_features = []
    for i, fid in enumerate(feats.ids):
        # Use the actual t-statistic from feats.types if available
        t_stat = feats.types[i] if isinstance(feats.types[i], (int, float)) else 0.0
        if abs(t_stat) > 2.0:
            strong_features.append((fid, t_stat))

    # Sort by absolute t-statistic
    strong_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # Select top features
    selected_features = [fid for fid, _ in strong_features[:MAX_DRIVERS]]

    # Check for correlations among selected features
    correlated_pairs = set()
    for i in range(len(selected_features)):
        for j in range(i+1, len(selected_features)):
            fid1, fid2 = selected_features[i], selected_features[j]
            col1 = feats.column(fid1)
            col2 = feats.column(fid2)
            if col1 != col2:  # Ensure different columns
                corr = np.corrcoef(feats.x[:, col1], feats.x[:, col2])[0,1]
                if abs(corr) >= 0.6:
                    # Prefer the feature with stronger effect size
                    if any(f == fid1 for f, _ in strong_features) and any(f == fid2 for f, _ in strong_features):
                        idx1 = next(k for k, (f, _) in enumerate(strong_features) if f == fid1)
                        idx2 = next(k for k, (f, _) in enumerate(strong_features) if f == fid2)
                        if abs(strong_features[idx1][1]) >= abs(strong_features[idx2][1]):
                            correlated_pairs.add((fid1, fid2))
                        else:
                            correlated_pairs.add((fid2, fid1))

    # Remove correlated features to avoid near-duplicates
    drivers = []
    used_features = set()

    for fid, _ in strong_features:
        if fid in used_features:
            continue
        # Check if this feature is correlated with any already selected feature
        is_correlated = False
        for d in drivers:
            if (d, fid) in correlated_pairs or (fid, d) in correlated_pairs:
                is_correlated = True
                break

        if not is_correlated:
            drivers.append(fid)
            used_features.add(fid)
            # Also mark correlated features as used
            for d in drivers:
                if (d, fid) in correlated_pairs or (fid, d) in correlated_pairs:
                    used_features.add(d)

        if len(drivers) >= MAX_DRIVERS:
            break

    # Build columns and products
    columns = tuple(selected_features)
    products = tuple(correlated_pairs)

    # Create loadings for weighted score (simple sum of selected features)
    loadings = {}
    for fid in selected_features:
        col_idx = feats.column(fid)
        # Use standardized values for loading
        mean_val = np.mean(feats.x[:, col_idx])
        std_val = np.std(feats.x[:, col_idx])
        if std_val > 0:
            loadings[fid] = 1.0 / std_val
        else:
            loadings[fid] = 0.0

    return Design(drivers=tuple(drivers), columns=columns, products=products, loadings=loadings)

